#!/usr/bin/env bash
# Generates the android/ platform folder (if missing) and applies the settings
# this app needs. Safe to re-run on an existing android/ folder.
#
#   bash scripts/bootstrap_android.sh
#
# android/ is generated by `flutter create` into a temporary directory and only
# the android/ folder is copied in, so lib/, test/ and pubspec.yaml are never
# touched.
set -euo pipefail

if ! command -v flutter >/dev/null 2>&1; then
  echo "flutter was not found on PATH. Install Flutter first: https://docs.flutter.dev/get-started/install" >&2
  exit 1
fi

PROJECT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$PROJECT_DIR"

if [ -d android ]; then
  echo "android/ already exists - keeping it and applying settings."
else
  TMP_DIR="$(mktemp -d)"
  trap 'rm -rf "$TMP_DIR"' EXIT
  flutter create --platforms=android --org com.example --project-name visitor_management "$TMP_DIR/visitor_management" >/dev/null
  cp -R "$TMP_DIR/visitor_management/android" ./android
  echo "Generated android/"
fi

MANIFEST="android/app/src/main/AndroidManifest.xml"
GRADLE_KTS="android/app/build.gradle.kts"
GRADLE_GROOVY="android/app/build.gradle"

# 1. Manifest entries. Each is added only if it is missing:
#    - INTERNET: the generated main manifest omits it, which breaks release builds
#    - CAMERA: QR scanning (camera hardware is not "required", so the app still
#      installs on devices without one)
#    - WRITE_EXTERNAL_STORAGE up to Android 9 (API 28): saving the QR pass to the
#      gallery; newer Android versions need no permission for this
python3 - "$MANIFEST" <<'PYEOF'
import sys

path = sys.argv[1]
text = open(path, encoding="utf-8").read()
entries = [
    ("android.permission.INTERNET",
     '<uses-permission android:name="android.permission.INTERNET"/>'),
    ("android.permission.CAMERA",
     '<uses-permission android:name="android.permission.CAMERA"/>'),
    ("android.permission.WRITE_EXTERNAL_STORAGE",
     '<uses-permission android:name="android.permission.WRITE_EXTERNAL_STORAGE" android:maxSdkVersion="28"/>'),
    ("android.hardware.camera",
     '<uses-feature android:name="android.hardware.camera" android:required="false"/>'),
]
missing = [(key, line) for key, line in entries if key not in text]
if missing:
    index = text.index("<application")
    line_start = text.rfind("\n", 0, index) + 1
    block = "".join("    " + line + "\n" for _, line in missing)
    text = text[:line_start] + block + text[line_start:]
    open(path, "w", encoding="utf-8").write(text)
    print("Added to AndroidManifest.xml: " + ", ".join(key for key, _ in missing))
else:
    print("AndroidManifest.xml already has all required entries")
PYEOF

# 2. App label shown under the launcher icon.
sed -i.bak -E 's/android:label="[^"]*"/android:label="Visitor Desk"/' "$MANIFEST" && rm -f "$MANIFEST.bak"

# 3. mobile_scanner needs a higher minSdk than Flutter's default.
for gradle in "$GRADLE_KTS" "$GRADLE_GROOVY"; do
  if [ -f "$gradle" ]; then
    sed -i.bak -E 's/minSdk(Version)?[[:space:]]*=?[[:space:]]*flutter\.minSdkVersion/minSdk = 23/' "$gradle" && rm -f "$gradle.bak"
    echo "Checked minSdk in $gradle (set to 23 if it used the Flutter default)"
  fi
done

flutter pub get
echo
echo "Done. Next:"
echo "  flutter run --dart-define=API_BASE_URL=\"https://<project-id>.mockapi.io/api/v1\""
